for index, (tag, prompt, opts, answer, reason) in enumerate(DATA, 1):
    record = json.loads((OUT / f'question-science-content-ma-iv-4-{index}.json').read_text())
    correct_index = opts.index(answer)
    target = TARGET_ANSWERS[index - 1]
    distractors = [text for option_index, text in enumerate(opts) if option_index != correct_index]
    position = ord(target) - 65
    arranged = distractors[:position] + [answer] + distractors[position:]
    record.update({'prompt': prompt, 'options': [{'id': chr(65 + i), 'text': text} for i, text in enumerate(arranged)], 'answer': {'value': target, 'explanation': reason + f' 正確答案為選項 {target}：「{answer}」。'}, 'solutionStrategy': '先辨認發電方式提供的服務，再用相同功能單位檢查生命週期、系統可靠度、地方衝擊、風險與公平分配。', 'solutionSteps': [f'讀題定位：圈出「{tag}」和題目要求比較的發電、環境或社會指標。', f'建立判準：{reason}', f'核對答案：選項 {target}「{answer}」符合判準。', '排除誘答：檢查是否只看平均值、額定值、單一階段或單一群體，並補回被省略的系統條件。', f'最後回查：確認「{answer}」的範圍足以支持題目結論。'], 'reviewStatus': 'draft', 'updatedAt': '2026-09-13', 'provenance': {**record.get('provenance', {}), 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究發電方式、新能源科技、生命週期、環境風險、電網與公共決策的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}})
    record['examPatternRefs'] = [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '發電方式與新能源的社會、環境影響', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}]
    (OUT / f'question-science-content-ma-iv-4-{index}.json').write_text(json.dumps(record, ensure_ascii=False, indent=2) + '\n')
print('rewrote', len(DATA), 'questions')
